A <- 400

rho <- 0.9
sigma_eps <- 0.03
set.seed(1234)

logy_a <- rnorm(A, mean = 0, sd = 0.05)
y_a <- exp(logy_a)

X_lower <- log(0.5)
X_upper <- log(2)

test_data <- list(A = A, logy_a = logy_a,

                  rho = rho, sigma_eps = sigma_eps,

                  X_lower = X_lower, X_upper = X_upper)
test_model3 <-

"

