int<lower=1> A;
real<lower=0, upper=1> rho;
real<lower=0> sigma_eps;
real logy_a[A];
real X_lower;
real X_upper;
}//end of data

parameters{
  real Z_a[A];
}
transformed parameters {

  real<lower=X_lower, upper=X_upper> X_a[A];
real<lower=0> sigma_eps_stat;

sigma_eps_stat <- sqrt(sigma_eps^2 / (1 - rho^2));

  X_a[1] <- X_lower + inv_logit(sigma_eps_stat * Z_a[1]) * (X_upper - X_lower);

  for (i in 2:A) {
